implementation:
long send_signal_to_thread(pid_t tgid, pid_t pid, int sig, const siginfo_t* info) {
    if (tgid <= 0 || pid <= 0) {
        return -EINVAL;
    }

    if (sig <= 0 || sig > _NSIG) {
        return -EINVAL;
    }

    if (info == NULL) {
        return -EINVAL;
    }

    if (info->si_code < 0 || info->si_code >= _NSIGCODE) {
        return -EINVAL;
    }

    // Assume a helper function exists to send the signal to the thread
    long result = send_signal_to_thread_helper(tgid, pid, sig, info);

    if (result < 0) {
        return result;
    }

    return 0;
}
